let csrf='', fields=[], tab='Passports', timer=null;
const root=document.getElementById('root');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=s=>({dob:'Date of birth',mrz:'MRZ',father_name:"Father’s name",mother_name:"Mother’s name",spouse_name:"Spouse’s name"}[s]||s.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase()));
const badge=s=>`<span class="badge ${esc(String(s).toLowerCase().replaceAll(' ','-'))}">${esc(s)}</span>`;
async function api(path,data){const o={credentials:'same-origin',headers:{}};if(data!==undefined){o.method='POST';o.headers['X-CSRFToken']=csrf;if(data instanceof FormData)o.body=data;else{o.headers['Content-Type']='application/json';o.body=JSON.stringify(data)}}const r=await fetch('/api/'+path,o);let b={};try{b=await r.json()}catch{}if(!r.ok)throw Error(b.error||'Request failed.');if(b.csrf)csrf=b.csrf;return b}
function error(e){const el=document.getElementById('global-error');if(el){el.textContent=e.message||String(e);el.style.display='flex'}else alert(e.message||String(e))}
async function boot(){try{const s=await api('session');fields=s.fields||[];s.authenticated?shell():login()}catch(e){root.innerHTML='<main class="login"><div class="error">'+esc(e.message)+'</div></main>'}}
function login(){clearInterval(timer);root.innerHTML=`<main class="login"><div class="login-card"><div class="brand-mark">PV</div><p class="eyebrow">YOUR PRIVATE WORKSPACE</p><h1>Passport Vault</h1><p class="muted">Sign in to automatically verify passports against your Master Excel.</p><div id="login-error" class="error" style="display:none"></div><form id="login-form"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><label>Authenticator or recovery code<input name="code" autocomplete="one-time-code" required></label><button class="primary">Sign in securely</button></form><small>Only the owner account created during setup can sign in.</small></div></main>`;document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();try{await api('login',Object.fromEntries(new FormData(e.currentTarget)));shell()}catch(x){const el=document.getElementById('login-error');el.textContent=x.message;el.style.display='block'}}}
function shell(){clearInterval(timer);root.innerHTML=`<div class="shell"><aside><div class="brand"><span class="brand-mark">PV</span><div>Passport Vault<small>Private document workspace</small></div></div><nav>${['Passports','Master Excel','Saved reports','Activity'].map(t=>`<button data-tab="${t}">${t}</button>`).join('')}</nav><div class="aside-bottom">Local processing<br><small>Your documents stay on this server.</small><button id="logout">Sign out</button></div></aside><main><header><div><p class="eyebrow">DOCUMENT VERIFICATION</p><h1 id="page-title"></h1></div><span class="private-label">Owner access</span></header><div id="global-error" class="error" style="display:none"></div><div id="page"></div><footer>Automatic verification compares OCR data with your active Master Excel. It does not authenticate document genuineness.</footer></main></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderTab()});document.getElementById('logout').onclick=async()=>{try{await api('logout',{});login()}catch(e){error(e)}};renderTab()}
function renderTab(){clearInterval(timer);document.getElementById('page-title').textContent=tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));if(tab==='Passports')renderPassports();else if(tab==='Master Excel')renderMaster();else if(tab==='Saved reports')renderReports();else renderActivity()}
async function renderPassports(status=''){const page=document.getElementById('page');page.innerHTML='<section class="panel">Loading passport records…</section>';async function load(){try{const d=await api('documents'+(status?'?status='+encodeURIComponent(status):''));page.innerHTML=`<section class="stats">${[['approved','Approved'],['review','Needs review'],['queued','Queued'],['processing','Processing'],['failed','Failed']].map(([k,n])=>`<button data-filter="${k}"><span>${n}</span><strong>${d.counts[k]||0}</strong></button>`).join('')}</section><section class="panel"><div class="section-head"><div><h2>Upload passports</h2><p>OCR runs locally and every passport is automatically checked against the active Master Excel.</p></div><span class="muted">PDF · JPG · PNG</span></div><div class="drop"><label class="file-button">Choose files<input id="passport-files" type="file" multiple accept=".pdf,.png,.jpg,.jpeg"></label><span>one file = one passport</span><small>For multi-page scans, combine pages into one PDF or tick the grouping option below.</small></div><div class="upload-options"><label class="check"><input id="group-files" type="checkbox">All selected files are pages of ONE passport</label><label>Printed language<select id="lang"><option value="eng">English / Latin MRZ</option><option value="eng+hin">English + Hindi</option><option value="eng+ara">English + Arabic</option></select></label><button id="upload-passports" class="primary">Upload & auto verify</button></div><div id="upload-state" class="muted"></div></section><section class="panel"><div class="section-head"><h2>Passport records <small>(${d.total})</small></h2><div><button id="delete-selected" class="danger" disabled>Delete selected (0)</button> <button id="refresh">Refresh</button></div></div><div class="table-wrap"><table><thead><tr><th><input id="select-all-docs" type="checkbox" aria-label="Select all records on this page"></th><th>Document</th><th>Passport number</th><th>Name</th><th>Status</th><th>Result</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr><td><input type="checkbox" data-select-doc="${x.id}" ${x.status==='processing'?'disabled title="Wait for processing to finish"':''}></td><td><strong>${esc(x.name)}</strong><small>${new Date(x.created).toLocaleString()}</small></td><td>${esc(x.fields.passport_number||'—')}</td><td>${esc(x.fields.full_name||'Awaiting extraction')}</td><td>${badge(x.status)}</td><td><small>${esc(x.verification?.reason||x.error?.replaceAll('_',' ')||'Processing')}</small></td><td><button data-open="${x.id}">Open</button></td></tr>`).join('')}</tbody></table></div>${!d.items.length?'<div class="empty"><h3>No records yet</h3><p>Configure Master Excel, then upload a passport.</p></div>':''}</section>`;const boxes=[...document.querySelectorAll('[data-select-doc]')];const selectAll=document.getElementById('select-all-docs'),del=document.getElementById('delete-selected');const sync=()=>{const usable=boxes.filter(x=>!x.disabled),selected=usable.filter(x=>x.checked);del.disabled=!selected.length;del.textContent=`Delete selected (${selected.length})`;selectAll.checked=usable.length>0&&selected.length===usable.length;selectAll.indeterminate=selected.length>0&&selected.length<usable.length};boxes.forEach(x=>x.onchange=sync);selectAll.onchange=()=>{boxes.filter(x=>!x.disabled).forEach(x=>x.checked=selectAll.checked);sync()};del.onclick=async()=>{const ids=boxes.filter(x=>x.checked&&!x.disabled).map(x=>x.dataset.selectDoc);if(!ids.length)return;const confirmText=prompt(`Delete ${ids.length} selected passport record(s)? Type DELETE to confirm.`);if(confirmText!=='DELETE')return;try{const r=await api('documents/bulk-delete',{ids,confirm:'DELETE'});alert(`${r.deleted} record(s) deleted.`);await load()}catch(e){error(e)}};document.getElementById('refresh').onclick=load;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDocument(b.dataset.open));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>renderPassports(b.dataset.filter));document.getElementById('upload-passports').onclick=uploadPassports}catch(e){error(e)}}await load();timer=null}
async function uploadPassports(){const input=document.getElementById('passport-files'),fs=[...(input.files||[])],state=document.getElementById('upload-state');if(!fs.length){state.textContent='Choose at least one passport file.';return}const grouped=document.getElementById('group-files').checked,groups=grouped?[fs]:fs.map(f=>[f]);state.textContent=`Uploading ${groups.length} passport group(s)…`;for(let i=0;i<groups.length;i++){const f=new FormData();groups[i].forEach(x=>f.append('files',x));f.append('language',document.getElementById('lang').value);try{await api('upload',f);state.textContent=`Queued ${i+1}/${groups.length}. OCR and Excel verification are running automatically…`}catch(e){state.textContent=`Group ${i+1}: ${e.message}`}}setTimeout(renderPassports,1200)}
async function openDocument(id){clearInterval(timer);const page=document.getElementById('page');page.innerHTML='<section class="panel">Opening record…</section>';try{const d=await api('documents/'+id),v=d.verification||{},comps=v.comparisons||{};page.innerHTML=`<section class="panel"><div class="section-head"><div><button id="back">← All passports</button><h2>${esc(d.name)}</h2></div>${badge(d.status)}</div>${v.reason?`<div class="${d.status==='approved'?'success-box':d.status==='failed'?'error':'notice'}"><strong>${d.status==='approved'?'Automatically approved':d.status==='failed'?'Verification failed':'Needs review'}</strong><p>${esc(v.reason)}</p>${v.master_name?`<small>Master: ${esc(v.master_name)}${v.sheet?' · '+esc(v.sheet)+' row '+esc(v.row):''}</small>`:''}</div>`:''}<div class="review-grid"><div class="preview"><div class="toolbar">${d.pages.map((p,i)=>`<button data-page="${p.id}">Page ${i+1}</button>`).join('')}</div><div id="preview-zone">${d.pages[0]?`<a href="/api/pages/${d.pages[0].id}" target="_blank"><img src="/api/pages/${d.pages[0].id}" alt="Passport preview"></a>`:'<div class="empty">Preview appears after extraction.</div>'}</div><details><summary>OCR text & MRZ checks</summary><pre>${esc(JSON.stringify(d.mrz_checks,null,2))}</pre><pre>${esc(d.evidence.map(p=>'PAGE '+p.page+'\n'+p.text).join('\n\n'))}</pre></details></div><div><h3>Automatic field verification</h3>${Object.keys(comps).length?`<div class="auto-compare">${Object.entries(comps).map(([f,x])=>`<div class="compare-card ${x.status==='Match'?'ok':'check'}"><div class="compare-title"><strong>${esc(label(f))}</strong>${badge(x.status||'Needs Review')}</div><div class="compare-values"><span><small>MASTER EXCEL</small>${esc(x.excel||'—')}</span><span><small>PASSPORT OCR</small>${esc(x.passport||'—')}</span></div></div>`).join('')}</div>`:'<div class="empty">No field comparison is available yet.</div>'}<details><summary>All OCR extracted fields</summary><div class="fields readonly-fields">${fields.map(f=>`<label>${esc(label(f))}<input readonly value="${esc(d.fields[f]||'')}"></label>`).join('')}</div></details></div></div>${d.warnings?.length?`<details><summary>OCR warnings</summary><div class="notice"><ul>${d.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div></details>`:''}<hr><button id="delete-doc" class="danger">Delete this record</button></section>`;document.getElementById('back').onclick=renderPassports;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>document.getElementById('preview-zone').innerHTML=`<a href="/api/pages/${b.dataset.page}" target="_blank"><img src="/api/pages/${b.dataset.page}" alt="Passport preview"></a>`);document.getElementById('delete-doc').onclick=async()=>{const x=prompt('Type DELETE to permanently delete this record');if(x==='DELETE'){try{await api('documents/'+id+'/delete',{confirm:'DELETE'});renderPassports()}catch(e){error(e)}}}}catch(e){error(e)}}
async function renderMaster(){const page=document.getElementById('page');let active={};try{active=await api('master')}catch(e){error(e)}page.innerHTML=`<section class="panel master-hero"><div><p class="eyebrow">MASTER DATABASE</p><h2>Excel data used for every passport verification</h2><p class="muted">Upload it once, map your columns once, then every new passport is checked automatically. No manual passport form filling.</p></div>${active.active?`<div class="active-master"><span>ACTIVE MASTER</span><strong>${esc(active.name)}</strong><small>${esc(active.config?.sheet||'')} · header row ${esc(active.config?.header||'')}</small></div>`:'<div class="notice">No Master Excel is active yet.</div>'}</section><section class="panel"><p class="eyebrow">STEP 1</p><h2>Upload Master Excel</h2><p class="muted">XLSX or UTF-8 CSV · up to 40 MB · maximum 1,000,000 rows · values only</p><label class="file-button">Choose spreadsheet<input id="master-file" type="file" accept=".xlsx,.csv"></label></section><div id="master-config"></div>`;document.getElementById('master-file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{const b=await api('workbooks',fd);masterConfig(b)}catch(x){error(x)}}}
function masterConfig(book){const area=document.getElementById('master-config'),names=Object.keys(book.sheets),sheet=names[0];area.innerHTML=`<section class="panel"><p class="eyebrow">STEP 2</p><h2>Map Excel columns to passport fields</h2><div class="toolbar"><label>Sheet<select id="master-sheet">${names.map(n=>`<option>${esc(n)}</option>`).join('')}</select></label><label>Header row<input id="master-header" type="number" value="1" min="1" max="20"></label><label>Date format<select id="date-format"><option value="DMY">Day / Month / Year</option><option value="MDY">Month / Day / Year</option></select></label></div><div id="master-preview"></div><div id="mapping" class="mapping"></div><div class="notice"><strong>Required for automatic approval:</strong> Passport number, Date of birth, Gender, Date of issue and Date of expiry. Full name and Nationality are display-only and do not affect approval.</div><button id="activate-master" class="primary">Save as Active Master</button><span id="master-saved" class="saved-ok"></span></section>`;const render=()=>{const sh=document.getElementById('master-sheet').value,h=Math.max(1,Number(document.getElementById('master-header').value)||1),rows=book.sheets[sh]||[],cols=rows[h-1]||[];document.getElementById('master-preview').innerHTML=`<div class="table-wrap mini"><table><thead><tr>${cols.map((c,i)=>`<th>${esc(c||'Column '+(i+1))}</th>`).join('')}</tr></thead><tbody>${rows.slice(h,h+4).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;document.getElementById('mapping').innerHTML=fields.filter(f=>f!=='mrz').map(f=>`<label>${esc(label(f))}${f==='passport_number'?' *':''}<select data-field="${f}"><option value="">Do not compare</option>${cols.map((c,i)=>`<option value="${i}">${i+1}: ${esc(c||'Unnamed')}</option>`).join('')}</select></label>`).join('')};document.getElementById('master-sheet').onchange=render;document.getElementById('master-header').onchange=render;render();document.getElementById('activate-master').onclick=async()=>{const mapping={};document.querySelectorAll('#mapping select').forEach(s=>{if(s.value!=='')mapping[s.dataset.field]=Number(s.value)});const required=['passport_number','dob','gender','date_of_issue','date_of_expiry'];if(required.some(f=>mapping[f]===undefined)){document.getElementById('master-saved').textContent='Map all five approval fields: Passport number, Date of birth, Gender, Date of issue and Date of expiry.';return}try{await api('master/activate',{workbook:book.id,sheet:document.getElementById('master-sheet').value,header:Number(document.getElementById('master-header').value),mapping,date_format:document.getElementById('date-format').value});document.getElementById('master-saved').textContent='✓ Master Excel activated. New passports will verify automatically.'}catch(e){error(e)}}}
async function renderReports(){const page=document.getElementById('page');try{const d=await api('reports');page.innerHTML=`<section class="panel"><h2>Saved comparison snapshots</h2><p class="muted">Legacy/manual comparison reports created by the earlier version remain available.</p>${d.items.map(r=>`<div class="saved-row"><span>${new Date(r.created).toLocaleString()}</span><button data-report="${r.id}">Open report</button></div>`).join('')||'<p class="empty">No saved reports.</p>'}</section>`;document.querySelectorAll('[data-report]').forEach(b=>b.onclick=async()=>{try{const r=await api('reports/'+b.dataset.report);page.innerHTML=`<button id="reports-back">← Saved reports</button><section class="panel results"><h2>Comparison results</h2><div class="result-counts">${['Match','Mismatch','Not Found','Needs Review','Invalid Row'].map(s=>`${badge(s)} <strong>${r.rows.filter(x=>x.status===s).length}</strong>`).join(' ')}</div><div class="table-wrap"><table><thead><tr><th>Row</th><th>Passport</th><th>Result</th><th>Reason</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(x.sheet)} ${esc(x.row)}</td><td>${esc(x.passport_number)}</td><td>${badge(x.status)}</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div></section>`;document.getElementById('reports-back').onclick=renderReports}catch(e){error(e)}})}catch(e){error(e)}}
async function renderActivity(){const page=document.getElementById('page');try{const d=await api('audit');page.innerHTML=`<section class="panel"><h2>Recent access history</h2><p class="muted">Latest 200 events. Field values and passport numbers are excluded.</p><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Record</th></tr></thead><tbody>${d.items.map(a=>`<tr><td>${new Date(a.at).toLocaleString()}</td><td>${esc(a.actor)}</td><td>${esc(a.action.replaceAll('_',' '))}</td><td class="mono">${esc(a.target||'—')}</td></tr>`).join('')}</tbody></table></div></section>`}catch(e){error(e)}}
boot();
